/* Isolated design prototype. All work/account/check data is fictional. No network model calls. */
const $ = s => document.querySelector(s);
const mark = (cls='') => `<img class="mark ${cls}" src="assets/rivune-icon.png" alt="Rivune">`;
const paths = {plus:'M9 3v12M3 9h12',chat:'M3 3h12v9H7l-4 3V3Z',search:'M12 12l4 4M13 8a5 5 0 1 1-10 0 5 5 0 0 1 10 0',folder:'M2 5h5l2 2h7v8H2V5Z',settings:'M9 6a3 3 0 1 0 0 6 3 3 0 0 0 0-6M9 1v3m0 10v3M1 9h3m10 0h3M3 3l2 2m8 8 2 2M3 15l2-2m8-8 2-2',plug:'M6 2v4m6-4v4M4 6h10v3a5 5 0 0 1-5 5v3M4 6v3a5 5 0 0 0 5 5',panel:'M2 3h14v12H2V3Zm9 0v12',arrow:'M9 14V3m-5 5 5-5 5 5',file:'M4 2h7l3 3v11H4V2Zm7 0v4h3',check:'m3 9 4 4 8-8',menu:'M3 4h12M3 9h12M3 14h12',link:'m6 12 6-6M7 5l2-2a4 4 0 0 1 6 6l-2 2M11 13l-2 2a4 4 0 0 1-6-6l2-2',stop:'M5 5h8v8H5V5Z'};
const icon = name => `<svg class="icon" viewBox="0 0 18 18" aria-hidden="true"><path d="${paths[name]||paths.chat}"/></svg>`;
const esc = v => String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={screen:'home',panel:'team',panelOpen:false,route:'Rivune',connection:0,setting:'General',stopped:false,draft:'',attachment:false,quality:'Quality first',access:'Discuss',context:true,refreshed:false,accounts:3,team:[0,1,2],chosenFile:'src/styles.css'};
const connectionData=[{name:'OpenAI',route:'Codex CLI',id:'Personal CLI · fixture',initial:'O',status:'Reported by connection',model:'GPT-6 Astra',detail:'Capability snapshot from a simulated CLI response. This mockup does not establish access through your account.'},{name:'Anthropic',route:'Claude Code CLI',id:'Personal CLI · fixture',initial:'A',status:'Request succeeded',model:'Claude · connection default',detail:'Example success state from a fixture. The active run pins its exact resolved model ID; no real request has been sent.'},{name:'Independent provider',route:'API',id:'Research account · fixture',initial:'P',status:'Authentication expired',model:'Review model · fixture',detail:'A third-provider design placeholder. Provider choice and capabilities remain open until the integration spike.'}];
const titles={home:'New conversation',active:'Fieldwork / Website',project:'Fieldwork / Website',decision:'A useful first business',approval:'Fieldwork / Website',error:'Fieldwork / Website'};
const btn=(label,action,cls='')=>`<button class="${cls}" data-action="${action}" ${({'attach':'Add attachment','mobile-nav':'Open navigation','remove-attachment':'Remove attachment'})[action]?'aria-label="'+({'attach':'Add attachment','mobile-nav':'Open navigation','remove-attachment':'Remove attachment'})[action]+'"':''}>${label}</button>`;
const nav=(label,screen,ic,selected=false)=>`<a class="nav ${selected?'selected':''}" href="#${screen}">${icon(ic)}<span>${label}</span></a>`;
function sidebar(){return `<aside class="sidebar" aria-label="Workspace navigation"><div class="traffic" aria-hidden="true"><i></i><i></i><i></i></div><button class="route row" data-action="routes">${state.route==='Rivune'?mark():`<span class="monogram">${esc(state.route[0])}</span>`}<span>${esc(state.route)}</span><span class="chevron">⌄</span></button>${nav('New conversation','home','plus',state.screen==='home')}${btn(icon('search')+'<span>Search</span><small>⌘ K</small>','search','nav')}<div class="nav-section">Projects</div>${nav('Fieldwork','project','folder',state.screen==='project')}<div class="nav-section">Recent</div>${nav('Website for Fieldwork','active','chat',['active','approval','error'].includes(state.screen))}${nav('A useful first business','decision','chat',state.screen==='decision')}<div class="sidebar-bottom">${nav('Connections','connections','plug',state.screen==='connections')}${nav('Settings','settings','settings',state.screen==='settings')}</div></aside>`}
function composer(){let active=state.screen==='active'&&!state.stopped;return `<div class="composer-wrap"><div class="composer">${state.attachment?`<div class="attachment">${icon('file')} Fieldwork brief.txt ${btn('×','remove-attachment')}</div>`:''}<textarea aria-label="Message" placeholder="${active?'Add a follow-up while the team works…':state.route==='Rivune'?'Ask anything, or give your team a project…':'Message '+state.route+' directly…'}" rows="2">${esc(state.draft)}</textarea><div class="composer-controls">${btn(icon('plus'),'attach')}${btn(icon('folder')+esc(state.access),'access')}${btn('Context','context')}${btn(state.route==='Rivune'?'Team · '+state.team.length:'Model','team')}${btn('<i class="quality-dot"></i>'+esc(state.quality),'quality')}<button class="send ${active?'stop':''}" data-action="${active?'stop':'send'}" aria-label="${active?'Stop simulated run':'Send simulated message'}">${icon(active?'stop':'arrow')}</button></div></div><p class="composer-note">${active?'Drafts stay editable while the team works.':'Only supported inputs appear for the selected route.'} · Design simulation</p></div>`}
const speaker=()=>`<div class="speaker">${mark()}<span>${esc(state.route)}</span></div>`;
function home(){return `<div class="home"><img class="mark" src="assets/rivune-icon.png" alt=""><h1>What are we working on?</h1><p>A question, an idea, a project.<br>Bring your team into it.</p><div class="suggestions">${btn('Build a website','example-build')}${btn('Think through a decision','example-decision')}${btn('Open a project','open-project')}</div></div>`}
function active(){return `<div class="reading"><div class="user-message">Build a website for Fieldwork, my fictional neighborhood repair studio. Make it warm and clear, with services, opening hours and a booking link. Keep it local for review.</div>${speaker()}<div class="answer"><p>I’m building a small, responsive site around one clear action: book a repair.</p><p>The layout and content are ready. The team is checking the integrated site now, including the booking link and compact-screen navigation.</p><div class="statusline"><span class="dot"></span>${state.stopped?'Stopped · unfinished work saved':'Checking the website at desktop and phone sizes'}</div><div class="artifact row">${icon('folder')}<div class="grow"><h3>Fieldwork website</h3><p>4 changed files · local workspace</p></div>${btn('View work ↗','show-preview')}</div><p class="small muted">${state.stopped?'No completion claim. Review the checkpoint before starting another attempt.':'You can keep writing here. Stop ends the current work and preserves its history.'}</p>${state.stopped?btn('Review saved checkpoint','checkpoint','secondary'):''}</div></div>`}
function decision(){return `<div class="reading"><div class="user-message">I have five hours a week and can reach local repair shops. Should I build a booking app, offer website improvements, or look for a better idea?</div>${speaker()}<div class="answer"><h2>Start with a small website service.</h2><p>Of these three options, it gives you the quickest way to learn what a real customer will pay for. Keep the first offer narrow: improve one shop’s service page and booking path.</p><p>This is a recommendation to test, not evidence that demand already exists. We have your constraints, but no customer interviews or paid pilots yet.</p><h3>Why it comes first</h3><div class="table-scroll"><table><thead><tr><th>Option</th><th>Fit for your week</th><th>Main uncertainty</th></tr></thead><tbody><tr><td>1. Website improvements</td><td>A small deliverable you can scope</td><td>Will a shop pay for it?</td></tr><tr><td>2. Booking app</td><td>More ongoing support</td><td>What existing tools fail to do</td></tr><tr><td>3. Keep exploring</td><td>Easy to postpone learning</td><td>Whether another problem is stronger</td></tr></tbody></table></div><h3>The useful disagreement</h3><p>One reviewer favored interviewing first. That concern holds: do not build a generic package this week. Use a rough example to start conversations, then shape the offer around what you hear.</p><h3>Your next five hours</h3><p>Speak with three shop owners, inspect their current booking path with permission, and ask what has caused missed work. Offer one tightly scoped pilot only if a repeated problem emerges.</p><p><strong>No stronger option found under these constraints.</strong> Revisit the choice if interviews expose a more urgent problem.</p><div class="footnotes">Basis: your supplied time and customer access. No market claims verified.<br>Confidence: provisional · 1 unresolved question: willingness to pay.</div>${btn('Inspect contributions & uncertainty →','show-team','link')}</div></div>`}
function project(){return `<div class="reading"><div class="user-message">Build a website for Fieldwork. Keep it local for review.</div>${speaker()}<div class="answer"><h2>Your site is ready to review.</h2><p>The site introduces the studio, explains three repair services, and gives visitors a clear way to book.</p><div class="artifact row">${icon('folder')}<div class="grow"><h3>Fieldwork</h3><p>Responsive website · 4 changed files</p></div>${btn('Open preview','show-preview','secondary')}</div><h3>What changed</h3><p>Added the landing page and responsive styling. The review caught a crowded mobile header; that is corrected in the integrated version.</p><div class="evidence-row"><span>Production build</span><span class="good">Passed · fixture</span></div><div class="evidence-row"><span>Booking link & navigation</span><span class="good">Passed · fixture</span></div><div class="evidence-row"><span>1440 px & 390 px visual review</span><span class="good">Reviewed · fixture</span></div><h3>Before this goes public</h3><p>The booking address and opening hours are example content. Replace them with approved details and review the site before deciding to deploy.</p><div class="footnotes">Illustrative outcome only. These checks were not run against a generated project. The preview is a designed sample.</div>${btn('Inspect changes and review evidence →','show-changes','link')}</div></div>`}
function approval(){return `<div class="reading"><div class="user-message">Use the Fieldwork brief and build the site in a new project folder.</div>${speaker()}<div class="answer"><h2>Choose where the team can work.</h2><p>The proposed team is ready. This job needs access to edit files and run local project commands.</p><div class="permission"><h3>Allow this project’s work?</h3><p>A single grant applies to every participant. The selected folder and sharing scope remain visible throughout the run.</p><dl><dt>Workspace</dt><dd>Projects / Fieldwork <span class="muted">(example)</span></dd><dt>Access</dt><dd>Create and edit files; run build, test and preview commands within this project.</dd><dt>Shared with</dt><dd>OpenAI · Personal CLI<br>Anthropic · Personal CLI<br>Independent provider · Research API</dd><dt>Context</dt><dd>This request, Fieldwork brief.txt, assigned files and review patches. Earlier chats excluded.</dd><dt>Limits</dt><dd>No publishing, purchases or access outside this workspace. New recipients need a new grant.</dd></dl><div class="actions">${btn('Keep discussing','deny')}${btn('Allow project work','approve','primary')}</div><p class="small muted" style="margin:15px 0 0">Design simulation: neither choice grants real filesystem or account access.</p></div></div></div>`}
function error(){return `<div class="reading"><div class="user-message">Finish the review of the Fieldwork website.</div>${speaker()}<div class="answer"><h2>The review needs your attention.</h2><p>The independent API connection expired before its review returned. Your files and completed contributions are saved.</p><div class="errorbox"><h3>Research API · Authentication expired</h3><p>Last completed checkpoint: integrated patch v3.<br>Still missing: the independent review and final verification.</p></div><p>Nothing has been marked complete. Reconnect this account to start the unfinished step again, or explicitly choose a different reviewer.</p><div class="row wrap">${btn('Review connection','open-connections','primary')}${btn('Choose another reviewer','replace-reviewer','secondary')}${btn('Inspect checkpoint','checkpoint','link')}</div><div class="footnotes">No automatic model, account or billing-route substitution. A retry is a new attempt linked to the saved checkpoint.</div></div></div>`}
function teamPanel(){let isDecision=state.screen==='decision';return `<h2>${isDecision?'How this recommendation formed':'A team for this job'}</h2><p>${isDecision?'Separate contributions, one decision.':'Three participants · responsibilities chosen for this task.'}</p><div class="member"><div class="member-head"><span class="monogram">O</span><div>GPT-6 Astra<small>OpenAI · Personal CLI · fixture</small></div></div><p>${isDecision?'Compared the options against time and reach.':'Owns page structure and integration.'}</p><div class="member-status">${isDecision?'Recommendation examined':'Implementation ready · v3'}</div></div><div class="member"><div class="member-head"><span class="monogram">A</span><div>Claude<small>Anthropic · Personal CLI · fixture</small></div></div><p>${isDecision?'Challenged the assumption that owners will pay.':'Owns service copy and reviews the layout patch.'}</p><div class="member-status">${isDecision?'Objection retained':'Mobile-header finding resolved'}</div></div><div class="member"><div class="member-head"><span class="monogram">P</span><div>Independent review model<small>Provider to be selected · API fixture</small></div></div><p>${isDecision?'Checks assumptions and the strength of the conclusion.':'Reviews the booking path and claims in the content.'}</p><div class="member-status">${state.screen==='error'?'Blocked · reconnect required':isDecision?'Evidence gap: customer demand':'Reviewing integrated patch v3'}</div></div><h3>${isDecision?'Open question':'Latest finding'}</h3><div class="review-finding"><b>${isDecision?'Will a shop pay for this outcome?':'Resolved · mobile navigation crowded the title'}</b><small>${isDecision?'No interviews or payment evidence yet. The pilot is a test, not a validated business.':'Reviewer inspected v2 at 390 px. Fix: collapse navigation. Integrated in v3; recheck required.'}</small></div><div class="panel-note">${isDecision?'Model agreement is not a source. This sample uses only the supplied constraints.':'Roles belong to this assignment, not to the vendors. Live runs would freeze model IDs and capability snapshots.'}</div>${btn('Inspect task assignments →','assignments','link')}`}
function previewPanel(){return `<div class="preview-toolbar"><span class="good">●</span><span>Designed preview · Fieldwork</span><span style="margin-left:auto">Responsive sample</span></div><div class="site-preview"><div class="sample-nav">fieldwork<span>REPAIR, CARE, REPEAT.</span></div><div class="sample-hero"><small>YOUR NEIGHBORHOOD REPAIR STUDIO</small><h2>Good things<br>deserve more time.</h2><p>Thoughtful repairs for the clothes and everyday objects you want to keep.</p><span class="sample-cta">Book a repair ↗</span></div><div class="sample-bands"><div><b>Wear it again.</b>Clothing & textile repairs</div><div><b>Keep it going.</b>Everyday object care</div></div></div><p class="small muted" style="margin-top:16px">Fictional studio. Static visual example, not a running website produced by agents.</p><div class="evidence-row"><span>Version under review</span><span>Integrated v3 · fixture</span></div><div class="evidence-row"><span>Review sizes</span><span>1440 / 390 px</span></div>${btn('Inspect verification trail →','show-checks','link')}`}
function filesPanel(){return `<h2>Project files</h2><p>Fieldwork · isolated workspace example</p><ul class="file-list">${['src/index.html','src/styles.css','src/navigation.js','tests/navigation.test.js'].map(f=>`<li><button data-action="file" data-file="${f}" ${state.chosenFile===f?'style="background:#3a3442"':''}>${icon('file')}${f}<span>M</span></button></li>`).join('')}</ul><h3>${esc(state.chosenFile)}</h3><div class="code">${state.chosenFile.endsWith('css')?'@media (max-width: 640px) {\n  .navigation {\n    flex-direction: column;\n    align-items: flex-start;\n  }\n}':state.chosenFile.endsWith('html')?'&lt;main&gt;\n  &lt;h1&gt;Good things deserve more time.&lt;/h1&gt;\n  &lt;a href="#booking"&gt;Book a repair&lt;/a&gt;\n&lt;/main&gt;':state.chosenFile.includes('test')?'test("navigation remains keyboard accessible",\n  async () =&gt; {\n    // Illustrative acceptance check\n  }\n);':'// Illustrative file content\n// Real file editing is not enabled here.'}</div><p>Read-only sample. The production Files panel would show the actual reviewed artifact version.</p>`}
function changesPanel(){return `<h2>Changes & verification</h2><p>Integrated v3 · 4 files · fixture evidence</p><h3>src/styles.css</h3><div class="code"><span class="diffremove">− .nav { gap: 32px; }</span>\n<span class="diffadd">+ .nav { gap: 20px; }\n+ @media (max-width: 640px) {\n+   .nav { flex-direction: column; }\n+ }</span></div><div class="review-finding"><b>Resolved · compact navigation</b><small>Claude reviewed the exact v2 patch. Integrator applied the correction in v3. Acceptance: no overlap at 390 px and keyboard access retained.</small></div><h3>Final integrated checks</h3><div class="evidence-row"><span>npm run build</span><span class="good">Exit 0*</span></div><div class="evidence-row"><span>npm test</span><span class="good">Passed*</span></div><div class="evidence-row"><span>Desktop + phone render</span><span class="good">Reviewed*</span></div><p style="margin-top:16px">*Illustrative receipts. No project commands were executed for this sample job.</p><div class="panel-note">A real completion state requires command logs and rendered evidence from the final integrated files. A model saying “done” cannot create these receipts.</div>`}
function panel(){return `<aside class="workpanel ${state.panel==='preview'?'wide':''}" aria-label="Work panel"><div class="panelbar" role="tablist" aria-label="Work views">${['team','files','changes','preview'].map(p=>`<button role="tab" aria-selected="${state.panel===p}" data-action="panel-tab" data-tab="${p}">${p[0].toUpperCase()+p.slice(1)}</button>`).join('')}<button class="close" data-action="close-panel" aria-label="Close work panel">×</button></div><div class="panel-body" role="tabpanel">${({team:teamPanel,files:filesPanel,changes:changesPanel,preview:previewPanel})[state.panel]()}</div></aside>`}
function settingsNav(){return `<nav class="settings-nav" aria-label="Settings categories"><h2>Settings</h2>${['General','Connections','Intelligence','Permissions','Privacy & Memory','Appearance','Devices','Updates'].map(s=>`<button class="nav ${(state.screen==='connections'?s==='Connections':state.setting===s)?'selected':''}" data-action="settings-category" data-category="${s}">${s}</button>`).join('')}</nav>`}
function connections(){let c=connectionData[state.connection];return `<div class="settings-inner"><div class="settings-heading"><div class="row between wrap"><h1>Connections</h1>${btn('+ Add connection','add-connection','secondary')}</div><p>Your accounts, models and supported capabilities.</p></div><div class="row between wrap" style="margin-bottom:19px"><span class="eyebrow">Fixture account state</span><select id="account-count" aria-label="Simulated number of connections"><option value="3" ${state.accounts===3?'selected':''}>Several connections</option><option value="1" ${state.accounts===1?'selected':''}>One connection</option><option value="0" ${state.accounts===0?'selected':''}>No connections</option></select></div>${state.accounts===0?`<div class="detailbox"><h2>Bring your first connection.</h2><p>Connect a supported CLI or API account. Rivune will show the models and capabilities that connection reports.</p>${btn('Choose connection type','add-connection','primary')}<p>Provider authentication remains with the provider. Subscription and API access are separate.</p></div>`:`<div class="connection-grid"><div>${connectionData.slice(0,state.accounts).map((d,i)=>`<button class="connection-row ${i===state.connection?'selected':''}" data-action="connection" data-index="${i}"><span class="monogram">${d.initial}</span><span><strong>${d.name}</strong><small>${d.route} · ${d.id}</small><small class="state">${i===2?'Authentication expired':i===1?'Request succeeded · fixture':'Catalog available · fixture'}</small></span></button>`).join('')}<p class="small muted" style="margin:20px 9px">Accounts shown here are design fixtures. No installed runtime or credentials have been inspected.</p></div><section class="detailbox"><div class="row between"><span class="tag">${c.route}</span>${btn(state.refreshed?'Refresh again':'Refresh models','refresh','secondary')}</div><h2>${c.name}</h2><p>${c.id}</p><p class="${state.refreshed?'warning':''}">${state.refreshed?'Refresh failed · saved catalog retained':'Last checked: 2 minutes ago · fixture'}</p><h3>Models on this connection</h3><div class="modelrow">${c.model}<small>${c.status} · fixture</small></div>${state.connection===0?'<div class="modelrow">Custom model ID<small>Available only if the adapter supports it.</small></div>':''}<p>${c.detail}</p><hr class="divider"><h3>Model settings</h3><p>Reasoning options come from this model and transport’s capability record. This fixture offers:</p><select aria-label="Fixture model reasoning effort"><option>High</option><option>Medium</option><option>Low</option></select><p style="margin-top:15px">Effort belongs to the model. Quality first is a separate Rivune orchestration policy.</p>${btn('Review a connection test','test-connection','link')}<h3>Connection-owned settings</h3><p>Import only supported non-secret preferences after a preview. Keys and full account permissions are never copied into a conversation.</p>${btn('Preview supported import','import-settings','link')}</section></div>`}</div>`}
const settingRow=(title,desc,control)=>`<div class="setting-row"><div><strong>${title}</strong><p>${desc}</p></div>${control}</div>`;
const toggle=(label,on=true)=>`<button class="toggle" role="switch" aria-label="${label}" aria-checked="${on}" data-action="toggle"></button>`;
function settings(){let section=state.setting;const views={General:`${settingRow('Open Rivune to','A quiet starting point. Projects stay one click away.','<select aria-label="Default start view"><option>New conversation</option><option>Last project</option></select>')}${settingRow('Restore previous windows','Keep your workspace when you return.',toggle('Restore previous windows'))}${settingRow('Send with Return','Use Shift–Return for a new line.',toggle('Send with Return'))}<h3 style="margin-top:32px">Designed for the Mac</h3><p class="muted small">Native menus, selection, focus and window restoration belong in the app implementation. This browser prototype demonstrates layout and selected interactions only.</p>`,Intelligence:`${settingRow('Default quality policy','Favor thorough work, with bounded review rounds.','<select aria-label="Default quality"><option>Quality first</option><option>Balanced</option><option>Custom</option></select>')}${settingRow('Propose a team','Choose from connected capabilities. Always allow a manual override.',toggle('Propose a team'))}${settingRow('Usage accounting','Show observed usage separately from estimates.',btn('Inspect policy','quality','secondary'))}<p class="small muted" style="margin-top:24px">No remaining subscription quota or dollar spend is fabricated when a provider does not report it.</p>`,Permissions:`${settingRow('Default access','Discussion until a workspace scope is chosen.','<select aria-label="Default access"><option>Discuss</option><option>Inspect selected project</option></select>')}${settingRow('Project work grants','One enforceable scope across all participants.',btn('See example','open-approval','secondary'))}${settingRow('External actions','Deployment, purchases and messaging require their own explicit authorization.','<span class="tag">Separate grant</span>')}`,'Privacy & Memory':`${settingRow('Include earlier messages','Share relevant messages in this conversation with the selected recipients.',toggle('Include earlier messages'))}${settingRow('Local conversation history','Retain results, files referenced and verification receipts.',toggle('Local conversation history'))}${settingRow('Sharing summary','See the accounts and context used before a new recipient is added.',btn('See summary','context','secondary'))}<p class="small muted" style="margin-top:24px">Proprietary provider account memory is not imported. Secrets remain in Keychain or provider-managed storage.</p>`,Appearance:`${settingRow('Appearance','Graphite surfaces with restrained accent color.','<select aria-label="Appearance"><option>Graphite</option></select>')}${settingRow('Reading size','Try the enlarged design state.',btn('Toggle larger text','large-text','secondary'))}${settingRow('Reduce motion','Status remains understandable with animation disabled.',toggle('Reduce motion'))}`,Devices:'<h2>Mac comes first.</h2><p class="muted">The iPhone direction is preserved. Pairing and relay are outside this first design prototype.</p><p class="small muted">Recommendation: hide Devices from the first release until a supported pairing path is ready.</p>',Updates:'<h2>Release information</h2><p class="muted">This is a local design review, with no installer or update service.</p><div class="detailbox"><h3>Before a public download appears</h3><p>A versioned manifest must identify the tested app, compatibility, release notes and checksums. Signing, notarization, browser download and clean-Mac installation are separate checks.</p></div>'};return `<div class="settings-inner"><div class="settings-heading"><h1>${section}</h1><p>One place for preferences that belong to Rivune.</p></div>${views[section]}</div>`}
function windowMarkup(){let setting=['settings','connections'].includes(state.screen);return `<section class="window" aria-label="Proposed Rivune Mac window">${sidebar()}<div class="content">${setting?`<div class="settings-shell">${settingsNav()}<main class="settings-content">${state.screen==='connections'?connections():settings()}</main></div>`:`<main class="conversation"><header class="titlebar">${btn(icon('menu'),'mobile-nav','mobile-nav')}<span>${titles[state.screen]}</span><button class="panel-toggle row" data-action="toggle-panel" aria-label="${state.panelOpen?'Close':'Open'} work panel">${icon('panel')}<span>Work</span></button></header><div class="transcript">${({home,active,decision,project,approval,error})[state.screen]()}</div>${composer()}</main>${state.panelOpen?panel():''}`}</div></section>`}
function website(){return `<article class="webconcept"><header class="webnav"><a href="#website" class="wordmark row">${mark()}Rivune</a><nav aria-label="Website concept"><a href="#web-work" data-scroll="web-work">How it works</a><a href="#web-connect" data-scroll="web-connect">Connections</a><a href="#web-download" data-scroll="web-download">Download</a></nav></header><section class="webhero"><div class="eyebrow">Your intelligence. Working together.</div><h1>Give your AI team<br>something real to do.</h1><p>A native workspace for turning questions into decisions, and ideas into working projects.</p><div class="actions"><a class="primary" href="#walkthrough">Explore a website build ↗</a><a class="secondary" href="#web-download" data-scroll="web-download">Release & source</a></div><p class="caption">Proposed product presentation · no release or compatibility claims.</p></section><figure class="hero-shot"><img src="assets/app-preview.png" alt="Proposed Rivune workspace showing a Fieldwork website result beside its designed preview"><figcaption class="shot-caption">Design concept. Replace with a current screenshot of the approved native app before publication.</figcaption></figure><section class="websection" id="web-work"><div class="webcolumns"><div><div class="index">01 / From brief to browser</div><h2>A website you can open.<br>A process you can inspect.</h2></div><div><p>Your team divides the work, reviews the actual changes, and checks the integrated result. The files, findings and local preview stay beside the conversation.</p><a class="link" href="#walkthrough">View the illustrated walkthrough →</a><p class="small">For release: use a real recorded build with versioned files and test receipts. This walkthrough is an illustration.</p></div></div></section><section class="websection"><div class="webcolumns"><div><div class="index">02 / A decision, with reasons</div><h2>Keep the useful disagreement.</h2></div><div><p>See the recommendation, the assumptions behind it, and what would change the answer. Agreement does not replace evidence.</p><a class="link" href="#decision">Explore a sample decision →</a></div></div></section><section class="websection" id="web-connect"><div class="index">03 / Bring supported connections</div><h2>Your models. Clear boundaries.</h2><p>CLI and API connections belong to their own accounts. The app checks available capabilities and makes sharing and usage visible.</p><div class="table-scroll"><table><thead><tr><th>Route</th><th>Setup path to document</th><th>Release compatibility</th></tr></thead><tbody><tr><td>Supported CLI</td><td>Install supported runtime; authenticate with provider</td><td>Pending integration verification</td></tr><tr><td>Supported API</td><td>Configure account through secure setup</td><td>Pending integration verification</td></tr></tbody></table></div><p class="small">Final compatibility entries must name tested adapter/runtime versions and limitations. A consumer subscription does not establish API access.</p></section><section class="websection" id="web-download"><div class="index">04 / Open source. Native Mac.</div><h2>A clear path from source to app.</h2><p>Keep release notes, platform requirements, privacy documentation and known limitations beside each version.</p><div class="row wrap">${btn('Download for Mac (.dmg) · unavailable','release-gates','secondary')}${btn('Source code (.zip) · design placeholder','source-info','secondary')}</div><p class="small" style="margin-top:17px">No downloads are attached to this concept. The source archive is independent of the signed, notarized installer.</p></section><footer class="webfooter"><span class="row">${mark()}Rivune · Proposed website</span><span>Documentation · Privacy · Changelog · Repository<br><small>Navigation targets will come from the verified release.</small></span></footer></article>`}
const steps=[
['Give the team a real brief','“Build a website for Fieldwork, a neighborhood repair studio. Include services, opening hours and a booking link. Keep it local.” The transcript stays a normal conversation. Rivune records the acceptance criteria: usable files, responsive rendering, a working local preview, and an inspected booking path.','No clarification unless a missing detail blocks useful work. Example content is explicitly labeled.','home'],
['Choose the workspace and sharing scope','The access sheet names the Fieldwork folder, the allowed edit/run actions, and every receiving connection. The prompt, attached brief and relevant patches are shared; unrelated conversations stay excluded.','Permission point: grant project work if it has not already been granted. A new provider recipient requires the applicable consent. Nothing in this walkthrough grants real access.','approval'],
['Plan, then challenge the plan','One participant proposes structure and acceptance checks. A second checks the brief for gaps: the booking destination is unknown, so use a labeled placeholder. A third checks how success will be measured. The concise transcript says what is happening; the panel holds assignments.','Assignments are task-specific. Astra owns layout/integration, Claude owns copy, and an independent API model reviews content in this fixture only. Roles can rotate on the next job.','active'],
['Work without conflicting edits','Contributors use isolated worktrees from the same version. The layout task owns page structure and CSS; the copy task returns service copy as a versioned artifact. The integrator assembles the patches. API review receives only its required artifacts.','No shared unsynchronized edits. The selected runtimes and Rivune’s tool boundary must actually enforce project scope before this capability is enabled.','active'],
['Review the concrete result','Reviewers receive exact patch v2 plus rendered screenshots. A layout review identifies crowded navigation at 390 px. The content review catches that example opening hours could read as confirmed facts. Findings include severity, evidence and a proposed correction.','Evidence point: a review refers to an artifact version, not a model’s self-report. The user can open each finding in Changes.','project'],
['Fix, integrate and verify','The integrator corrects the compact header and labels sample business details in v3. A different participant checks those corrections. Build, navigation checks and desktop/phone inspection run against v3. The preview refers to that same version.','The real app must attach actual command output and screenshots here. This design contains illustrative receipts only; it has not executed this project job.','project'],
['Deliver one usable outcome','The final answer links the project and local preview, summarizes changes, and states what passed and what is unresolved. The booking URL and hours still need approved real values. Stop once the agreed local-review criteria are met; further rounds need a meaningful reason.','Permission point: deployment remains a separate authorized action. A public launch never follows merely from “build a website.”','project'],
['Recover honestly if interrupted','If the API account expires, the job remains incomplete and saves its last known checkpoint. The user sees what finished, what is missing, and the named account that failed. Reconnect or explicitly replace the reviewer, then start a linked retry.','Stop cancels the attempt. “Resume” is used only for supported runtime continuation; otherwise the action says “Retry unfinished step.”','error']
];
function walkthrough(){return `<article class="reviewdoc"><div class="eyebrow">One end-to-end job · proposed behavior</div><h1>From “build this” to a website you can inspect.</h1><p class="intro">A realistic Fieldwork walkthrough ties the screens together. This is a designed example, not a claim that the current app can execute the job.</p><div class="step-list">${steps.map(s=>`<section class="step"><div><h2>${s[0]}</h2><p>${s[1]}</p><p class="step-meta">${s[2]}</p><a href="#${s[3]}">Open the corresponding screen →</a></div></section>`).join('')}</div><h2>The proof required after design approval</h2><p>Use a fresh workspace and real supported connections. Save task ownership, artifact versions, reciprocal findings, integrated diffs, command exits, responsive screenshots and a usable local URL. A three-participant mixed CLI/API team must finish without any vendor-specific scheduling requirement.</p><a class="link" href="#contract">Review scope and open decisions →</a></article>`}
function contract(){return `<article class="reviewdoc"><div class="eyebrow">Product contract · proposed release scope</div><h1>One workspace.<br>A chosen team.<br>A usable result.</h1><p class="intro">Rivune coordinates supported AI connections to understand a job, divide it, challenge the work, verify the integrated result and deliver it clearly. Direct conversation remains simple.</p><div class="contract-grid"><section><h2>Established</h2><ul><li>Rivune’s existing name and mark.</li><li>Native Apple direction; restrained graphite and purple.</li><li>Configurable CLI/API team membership and direct mode.</li><li>Real coding, websites and candid decisions.</li><li>Quality-first personal use and open source.</li><li>One primary result with inspectable work and uncertainty.</li></ul></section><section><h2>Recommended here</h2><ul><li>Chat first; project context opens a work panel.</li><li>Mac first, one personal/public codebase.</li><li>Team, Files, Changes and Preview share one panel.</li><li>Compact windows replace the detail pane with the work view.</li><li>Hide voice and Devices until a supported path exists.</li><li>One independent provider proves extensibility.</li></ul></section></div><h2>First complete release</h2><p>Approved Mac UI; supported configurable CLI/API connections; model discovery and honest stale/no-access states; variable teams; real file editing, tests and preview; research/decision review; direct chat; history; Stop and recovery; enforceable access; visible usage policy; verified source and installer distribution.</p><h2>Deferred</h2><p>Unknown CLIs without adapters, proprietary provider-memory imports, broad voice/video/image features, cloud relay, widgets and simultaneous iPhone redesign. No attractive dead controls for those features in the release.</p><h2>What still needs a decision</h2><p>Approve or revise this layout and release scope. Chat-first remains the recommendation, not an accepted preference. The independent provider, orchestration process boundary, containment mechanism, runtime recovery and distribution credentials need bounded engineering investigation later.</p><h2>Implementation gates</h2><p>Rendered design approval → connection and discovery proof → one real website job → representative evaluation → complete Mac product and distribution → broader integrations.</p><section class="feedback"><h2>Review notes</h2><p class="small">Notes are saved only in this browser. Export them to preserve them with the planning documents. Nothing here approves implementation automatically.</p><label for="feedback">What to keep, what to change, and your scope decision</label><textarea id="feedback" placeholder="Keep…\nChange…\nChat-first or project-first…\nFirst-release scope…"></textarea><div class="row wrap">${btn('Save notes locally','save-feedback','secondary')}${btn('Export review notes','export-feedback','primary')}<span id="feedback-status" class="small muted" role="status"></span></div></section></article>`}
let lastRendered='';
function render(){ const scroll=lastRendered===state.screen?$('.transcript')?.scrollTop||0:0; lastRendered=state.screen; $('#screen').value=state.screen;$('#stage').innerHTML=({website,walkthrough,contract})[state.screen]?.()||windowMarkup();if($('.transcript'))$('.transcript').scrollTop=scroll;if(state.screen==='contract') {try{$('#feedback').value=localStorage.getItem('rivune-design-review-01')||''}catch{}} }
function navigate(screen){if(!$('#screen').querySelector(`option[value="${screen}"]`))screen='home';state.screen=screen;state.panelOpen=['active','project','error'].includes(screen);state.panel=screen==='project'?'preview':'team';state.stopped=false;state.draft='';state.access=['active','project','error'].includes(screen)?'Edit & run':'Discuss';render();window.scrollTo(0,0)}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',5000)}
function modal(title,body){$('#dialog').innerHTML=`<button class="modalclose" data-action="close-dialog" aria-label="Close dialog">×</button><h2 id="dialog-title">${title}</h2>${body}`;$('#dialog').showModal()}
function closeModal(){if($('#dialog').open)$('#dialog').close()}
function showPanel(tab){state.panelOpen=true;state.panel=tab;render()}
document.addEventListener('input',e=>{if(e.target.matches('.composer textarea'))state.draft=e.target.value});
document.addEventListener('change',e=>{if(e.target.id==='screen')location.hash=e.target.value;if(e.target.id==='account-count'){state.accounts=Number(e.target.value);state.connection=0;render()}});
$('#compact').onclick=()=>{document.body.classList.toggle('compact');$('#compact').setAttribute('aria-pressed',document.body.classList.contains('compact'))};
function toggleText(){document.body.classList.toggle('large-text');$('#textsize').setAttribute('aria-pressed',document.body.classList.contains('large-text'))}$('#textsize').onclick=toggleText;
document.addEventListener('click',e=>{
 const scroll=e.target.closest('[data-scroll]');if(scroll){e.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:'instant'});return}
 const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;
 switch(action){
 case 'close-dialog':closeModal();break;
 case 'routes':modal('Choose how to work',`<p>Rivune coordinates a team. Direct uses one connection. These are fixture accounts.</p><div class="dialog-options">${['Rivune',...connectionData.slice(0,state.accounts).map(x=>x.name)].map(n=>`<button data-action="choose-route" data-route="${n}">${n}<small>${n==='Rivune'?'Coordinated work · configurable participants':'Direct conversation · fixture connection'}</small></button>`).join('')}</div>`);break;
 case 'choose-route':state.route=el.dataset.route;closeModal();render();break;
 case 'search':modal('Search conversations',`<form class="dialog-form" onsubmit="return false"><label>Search<input id="search-query" type="text" placeholder="Try Fieldwork" autofocus></label></form><div class="dialog-options"><a class="nav" href="#project" data-action="close-dialog">Fieldwork / Website</a><a class="nav" href="#decision" data-action="close-dialog">A useful first business</a></div><p>Fixture search: two example conversations.</p>`);$('#search-query').oninput=ev=>{document.querySelectorAll('#dialog a').forEach(a=>a.hidden=!a.textContent.toLowerCase().includes(ev.target.value.toLowerCase()))};break;
 case 'example-build':location.hash='approval';break;
 case 'example-decision':location.hash='decision';break;
 case 'open-project':modal('Open a project',`<p>In the native app, choose a folder with the system picker. This prototype uses a fictional workspace.</p><div class="dialog-options"><button data-action="open-approval">Projects / Fieldwork<small>Choose access and recipients before the team starts.</small></button></div>`);break;
 case 'open-approval':closeModal();location.hash='approval';break;
 case 'attach':modal('Add context',`<p>This route’s fixture supports text files. The attachment can be removed before sending.</p><div class="dialog-options"><button data-action="attach-fixture">Fieldwork brief.txt<small>Example services and design brief · shared with the selected team</small></button></div><p>Images, microphone and other unsupported inputs are absent from this proposed first release.</p>`);break;
 case 'attach-fixture':state.attachment=true;closeModal();render();break;
 case 'remove-attachment':state.attachment=false;render();break;
 case 'access':modal('Access for this conversation',`<p>All participants use the same permission boundary.</p><div class="dialog-options">${['Discuss','Inspect project','Edit & run project'].map(n=>`<button data-action="choose-access" data-access="${n}">${n}<small>${n==='Discuss'?'Use selected text and attachments':n==='Inspect project'?'Read only within a selected workspace':'Requires a named workspace and sharing grant'}</small></button>`).join('')}</div>`);break;
 case 'choose-access':if(el.dataset.access==='Edit & run project'){closeModal();location.hash='approval'}else{state.access=el.dataset.access;closeModal();render()}break;
 case 'context':modal('Context & recipients',`<form class="dialog-form"><label><input type="checkbox" id="include-context" ${state.context?'checked':''}>Include earlier messages</label><p>Share relevant messages in this conversation, not unrelated chats or proprietary account memory.</p></form><h3>Receives this run’s selected context</h3><p>${state.route==='Rivune'?'OpenAI · Personal CLI<br>Anthropic · Personal CLI<br>Independent provider · Research API':esc(state.route)+' · direct fixture'}</p><p>A newly added recipient requires the applicable consent.</p>${btn('Apply to draft','apply-context','primary')}`);break;
 case 'apply-context':state.context=$('#include-context').checked;closeModal();toast('Draft sharing preference updated in the mockup.');break;
 case 'team':modal(state.route==='Rivune'?'Team for the next run':'Direct model',`<p>Capabilities and the job determine eligibility. Sample choices only; this does not configure real accounts.</p><div class="dialog-form">${connectionData.map((c,i)=>`<label><input type="checkbox" data-member="${i}" ${state.team.includes(i)?'checked':''} ${state.route!=='Rivune'?'disabled':''}>${c.name}<small class="muted"> · ${c.model}</small></label>`).join('')}</div><p>Per-model effort belongs with its connection. Quality policy is set separately.</p>${state.route==='Rivune'?btn('Apply team to draft','apply-team','primary'):''} ${btn('Inspect model settings','open-connections','secondary')}`);break;
 case 'apply-team': {const selected=[...document.querySelectorAll('[data-member]:checked')].map(e=>Number(e.dataset.member));if(!selected.length){toast('Choose at least one participant.');break}state.team=selected;closeModal();render();toast('Draft team updated. Existing run assignments remain frozen.');break;}
 case 'quality':modal('Quality policy',`<p>Choose how Rivune coordinates work. These policies are not provider reasoning levels.</p><div class="dialog-options">${['Quality first','Balanced','Custom'].map(n=>`<button data-action="choose-quality" data-quality="${n}">${n}<small>${n==='Quality first'?'Thorough review within explicit limits':n==='Balanced'?'A smaller team and fewer review rounds':'Set measurable time, request and concurrency limits'}</small></button>`).join('')}</div><p>Observed cost: unavailable in this fixture. A CLI subscription may not report precise remaining quota. No silent account rotation.</p>`);break;
 case 'choose-quality':state.quality=el.dataset.quality;closeModal();render();toast('Mockup quality policy changed. Live limits still require an implementation.');break;
 case 'stop':state.stopped=true;render();toast('Simulation stopped. Partial work is preserved; the job is incomplete.');break;
 case 'send':if(!state.draft.trim()){toast('Type a message, or choose a sample prompt.');break}modal('Draft preview',`<p>${esc(state.draft)}</p><p>This design prototype does not contact models. Explore the fixture job to review the proposed behavior.</p>${btn('Explore the website job','example-build','primary')}`);break;
 case 'toggle-panel':state.panelOpen=!state.panelOpen;render();break;
 case 'close-panel':state.panelOpen=false;render();break;
 case 'panel-tab':showPanel(el.dataset.tab);break;
 case 'show-preview':showPanel('preview');break;
 case 'show-team':showPanel('team');break;
 case 'show-changes':case 'show-checks':showPanel('changes');break;
 case 'file':state.chosenFile=el.dataset.file;render();break;
 case 'mobile-nav':$('.window').classList.toggle('nav-open');break;
 case 'connection':state.connection=Number(el.dataset.index);state.refreshed=false;render();break;
 case 'refresh':state.refreshed=!state.refreshed;render();toast(state.refreshed?'Simulated refresh failed. Last successful catalog retained and marked stale.':'Simulated catalog refresh succeeded. Active runs keep their original snapshot.');break;
 case 'settings-category':state.setting=el.dataset.category;if(state.setting==='Connections'){location.hash='connections'}else if(state.screen==='settings'){render()}else{location.hash='settings'}break;
 case 'toggle':el.setAttribute('aria-checked',el.getAttribute('aria-checked')!=='true');break;
 case 'large-text':toggleText();break;
 case 'open-connections':closeModal();location.hash='connections';break;
 case 'add-connection':modal('Add a supported connection',`<p>Choose a route. Provider authentication happens through its supported flow; no secrets are entered in this prototype.</p><div class="dialog-options"><button data-action="cli-setup">Supported CLI<small>Detect known runtimes; inspect supported integration capabilities.</small></button><button data-action="api-setup">API account<small>Choose a reviewed adapter and secure account configuration.</small></button></div><p>Unknown CLIs require an adapter or supported common protocol.</p>`);break;
 case 'cli-setup':case 'api-setup':closeModal();modal(action==='cli-setup'?'CLI setup preview':'API setup preview',`<p>1. Choose a supported ${action==='cli-setup'?'runtime':'provider adapter'}.<br>2. Authenticate with the provider.<br>3. Inspect capabilities and model states.<br>4. Review a test request before sending.<br>5. Add eligible models to a team.</p><p>No detection, authentication or key storage runs in this design prototype.</p>${btn('View example connection','open-connections','primary')}`);break;
 case 'test-connection':modal('Review a connection test',`<p>A real test would send a short prompt to the named connection and may consume account usage.</p><div class="detailbox"><p>Recipient: ${connectionData[state.connection].name}<br>Prompt: “Reply with OK.”<br>Tool access: none<br>Earlier messages: excluded</p></div><p>Design stage: live testing is outside scope. This control demonstrates the review step only.</p>${btn('Close test preview','close-dialog','primary')}`);break;
 case 'import-settings':modal('Preview settings import',`<p>Only documented, allowlisted, non-secret preferences can be copied after review.</p><div class="table-scroll"><table><tr><th>Preference</th><th>Proposed change</th></tr><tr><td>Default model</td><td>From supported connection metadata</td></tr><tr><td>Credentials & tool permissions</td><td>Excluded</td></tr></table></div><p>Provider configuration is never silently overwritten. No import is performed in this mockup.</p>`);break;
 case 'approve':state.access='Edit & run';state.context=false;location.hash='active';toast('Design simulation only: showing the granted-work state.');break;
 case 'deny':state.access='Discuss';location.hash='home';toast('Simulation remains in discussion mode.');break;
 case 'checkpoint':modal('Saved checkpoint · fixture',`<p>Integrated patch v3 is preserved with its contribution history.</p><div class="evidence-row"><span>Layout and copy</span><span>Saved</span></div><div class="evidence-row"><span>Independent review</span><span class="warning">Incomplete</span></div><div class="evidence-row"><span>Final verification</span><span class="warning">Not run</span></div><p>Reconnect before retrying the unfinished step. A fresh attempt retains this checkpoint’s provenance.</p>${btn('Review failed connection','open-connections','secondary')}`);break;
 case 'replace-reviewer':modal('Change reviewer explicitly',`<p>The replacement receives the request and exact review artifacts. Confirm the recipient and billing route before retrying.</p><div class="dialog-options"><button data-action="replacement-preview">Anthropic · Personal CLI<small>Existing recipient · illustrative alternative</small></button></div><p>Do not select a participant to review its own contribution without recording that limitation.</p>`);break;
 case 'replacement-preview':toast('Replacement preview only. No account or assignment changed.');break;
 case 'assignments':modal('Versioned assignments · fixture',`<div class="table-scroll"><table><tr><th>Owner</th><th>Deliverable</th><th>Check</th></tr><tr><td>Participant A</td><td>Layout patch</td><td>Responsive render</td></tr><tr><td>Participant B</td><td>Service copy</td><td>Matches supplied brief</td></tr><tr><td>Participant C</td><td>Independent review</td><td>Evidence-backed findings</td></tr></table></div><p>Integrator assembles v3. Reviewers receive exact artifact versions. Task roles can rotate on the next job.</p>`);break;
 case 'release-gates':modal('Mac installer · not available',`<p>This is a design artifact. A public DMG needs signing, notarization, checksum verification, an actual browser download and a clean-Mac install/open test.</p><p>Those release checks have not been performed here.</p>`);break;
 case 'source-info':modal('Source download · separate from installer',`<p>The release website will link a versioned source archive independently of installer readiness. No new archive is packaged or linked by this design prototype.</p>`);break;
 case 'save-feedback':try{localStorage.setItem('rivune-design-review-01',$('#feedback').value);$('#feedback-status').textContent='Saved in this browser.'}catch{toast('Browser storage unavailable. Export notes instead.')}break;
 case 'export-feedback':{const text='# Rivune design review 01 — feedback\n\nStatus: user notes; approval only if explicitly stated below.\n\n'+$('#feedback').value+'\n';const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/markdown'}));a.download='rivune-review-feedback.md';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);break}
 }
});
document.addEventListener('keydown',e=>{if(e.key==='Tab'&&$('#dialog').open){const items=[...$('#dialog').querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select,textarea')].filter(x=>x.getClientRects().length);const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('[data-action="search"]')?.click()}if(e.key==='Escape'){if($('.window.nav-open'))$('.window').classList.remove('nav-open');else if(state.panelOpen&&!$('#dialog').open){state.panelOpen=false;render()}}});
window.addEventListener('hashchange',()=>{closeModal();navigate(location.hash.slice(1))});navigate(location.hash.slice(1)||'home');
